173	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
174	        Owner owner = this.clinicService.findOwnerById(ownerId);
175	        if (owner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        HttpHeaders headers = new HttpHeaders();
179	        Pet pet = petMapper.toPet(petFieldsDto);
180	        owner.setId(ownerId);
181	        pet.setOwner(owner);
182	        pet.getType().setName(null);
183	        this.clinicService.savePet(pet);
184	        PetDto petDto = petMapper.toPetDto(pet);
185	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
186	            .buildAndExpand(pet.getId()).toUri());
187	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
193	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
194	        if (currentOwner != null) {
195	            Pet currentPet = this.clinicService.findPetById(petId);
196	            if (currentPet != null) {
197	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
198	                currentPet.setName(petFieldsDto.getName());
199	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
200	                this.clinicService.savePet(currentPet);
201	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
202	            }
203	        }
204	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
210	        HttpHeaders headers = new HttpHeaders();
211	        Visit visit = visitMapper.toVisit(visitFieldsDto);
212	        Pet pet = new Pet();
213	        pet.setId(petId);
214	        visit.setPet(pet);
215	        this.clinicService.saveVisit(visit);
216	        VisitDto visitDto = visitMapper.toVisitDto(visit);
217	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
218	            .buildAndExpand(visit.getId()).toUri());
219	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
220	    }
221	
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
226	        Owner owner = this.clinicService.findOwnerById(ownerId);
227	        if (owner != null) {
228	            Pet pet = owner.getPet(petId);
229	            if (pet != null) {
230	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
231	            }
232	        }
233	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	    }
235	
236	    /**
237	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
238	     * offending field is collected so the caller learns exactly which values must be supplied.
239	     *
240	     * @param ownerFieldsDto the submitted owner payload
241	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
242	     *         telephone is missing or blank
243	     */
244	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
245	        List<String> missingFields = new ArrayList<>();
246	        if (isBlank(ownerFieldsDto.getFirstName())) {
247	            missingFields.add("firstName");
248	        }
249	        if (isBlank(ownerFieldsDto.getLastName())) {
250	            missingFields.add("lastName");
251	        }
252	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
253	            missingFields.add("address");
254	        }
255	        if (isBlank(ownerFieldsDto.getCity())) {
256	            missingFields.add("city");
257	        }
258	        if (isBlank(ownerFieldsDto.getTelephone())) {
259	            missingFields.add("telephone");
260	        }
261	        if (!missingFields.isEmpty()) {
262	            throw new MissingOwnerFieldsException(missingFields);
263	        }
264	    }
265	
266	    private boolean isBlank(String value) {
267	        return value == null || value.isBlank();
268	    }
269	
270	    /**
271	     * Counts the existing owners who, before this create, already share the given first and last name.
272	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
273	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
274	     * case or spacing still count as the same name.
275	     *
276	     * @param firstName the first name of the owner being created
277	     * @param lastName the last name of the owner being created
278	     * @return the number of existing owners sharing both names (zero when none)
279	     */
280	    private int countNamesakes(String firstName, String lastName) {
281	        String first = normalizeHouseholdField(firstName);
282	        String last = normalizeHouseholdField(lastName);
283	        return (int) this.clinicService.findAllOwners().stream()
284	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
285	                && normalizeHouseholdField(existing.getLastName()).equals(last))
286	            .count();
287	    }
288	
289	    /**
290	     * Builds an owner's customer code, formatted '&lt;LAST3&gt;-&lt;NNNN&gt;'. LAST3 is the
291	     * upper-cased first three letters of the last name; NNNN is a global 4-digit zero-padded
292	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
293	     *
294	     * @param lastName the owner's last name
295	     * @return the formatted customer code
296	     */
297	    private String generateCustomerCode(String lastName) {
298	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
299	        int sequence = this.clinicService.findAllOwners().size() + 1;
300	        return String.format("%s-%04d", last3, sequence);
301	    }
302	
303	    /**
304	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
305	     * customerCode is the owner's customer code and YY is the last two digits of the
306	     * registrationDate year (e.g. 'SMI-0007-M26').
307	     *
308	     * @param customerCode the owner's customer code
309	     * @param registrationDate the owner's registration date
310	     * @return the formatted membership number
311	     */
312	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
313	        String yy = String.format("%02d", registrationDate.getYear() % 100);
314	        return customerCode + "-M" + yy;
315	    }
316	
317	    /**
318	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
319	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
320	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
321	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
322	     * stored and returned.
323	     *
324	     * @param telephone the raw telephone value from the request
325	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
326	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
327	     */
328	    private String normalizeTelephone(String telephone) {
329	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
330	        String e164;
331	        if (cleaned.startsWith("+")) {
332	            e164 = cleaned;
333	        } else {
334	            String national = cleaned;
335	            if (national.startsWith("0")) {
336	                national = national.substring(1);
337	            }
338	            e164 = "+61" + national;
339	        }
340	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
341	            throw new InvalidOwnerFieldsException(List.of("telephone"));
342	        }
343	        return e164;
344	    }
345	
346	    /**
347	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
348	     * left unset. When a value is present it must be a syntactically valid address; the normalized
349	     * form stored and returned is the value lower-cased.
350	     *
351	     * @param email the raw email value from the request, or {@code null} when none was supplied
352	     * @return the lower-cased email, or {@code null} when no email was supplied
353	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
354	     */
355	    private String normalizeEmail(String email) {
356	        if (email == null || email.isBlank()) {
357	            return null;
358	        }
359	        if (!EMAIL_PATTERN.matcher(email).matches()) {
360	            throw new InvalidOwnerFieldsException(List.of("email"));
361	        }
362	        return email.toLowerCase(Locale.ROOT);
363	    }
364	
365	    /**
366	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
367	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
368	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
369	     * normalized form is what gets stored, returned and used for every address comparison (the
370	     * required-field check, household duplicate detection and the shared household id).
371	     *
372	     * @param address the raw address value from the request, or {@code null}
373	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
374	     */
375	    private String normalizeAddress(String address) {
376	        if (address == null) {
377	            return "";
378	        }
379	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
380	        if (collapsed.isEmpty()) {
381	            return "";
382	        }
383	        String[] tokens = collapsed.split(" ");
384	        for (int i = 0; i < tokens.length; i++) {
385	            switch (tokens[i]) {
386	                case "ST" -> tokens[i] = "STREET";
387	                case "RD" -> tokens[i] = "ROAD";
388	                case "AVE" -> tokens[i] = "AVENUE";
389	                default -> { }
390	            }
391	        }
392	        return String.join(" ", tokens);
393	    }
394	
395	    /**
396	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
397	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
398	     * directly and is therefore independent of the punctuation a caller supplied.
399	     *
400	     * @param e164Telephone the E.164 telephone of the owner being created
401	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
402	     */
403	    private void rejectDuplicateTelephone(String e164Telephone) {
404	        boolean inUse = this.clinicService.findAllOwners().stream()
405	            .map(Owner::getTelephone)
406	            .filter(existing -> existing != null)
407	            .anyMatch(e164Telephone::equals);
408	        if (inUse) {
409	            throw new DuplicateOwnerTelephoneException(e164Telephone);
410	        }
411	    }
412	
413	    /**
414	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
415	     * last name and a normalized address: last names are compared case-insensitively after whitespace
416	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
417	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
418	     * abbreviation still count as the same household.
419	     * <p>
420	     * When the owner's last name and address already belong to at least one other owner the behaviour
421	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
422	     * household. If it is true the create is allowed and every member of the household - the existing
423	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
424	     * read. When no other owner shares the last name and address no identifier is assigned.
425	     *
426	     * @param owner the owner being created
427	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
428	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
429	     *         address and {@code sharesHousehold} is not true
430	     */
431	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
432	        String lastName = normalizeHouseholdField(owner.getLastName());
433	        String address = normalizeAddress(owner.getAddress());
434	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
435	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
436	                && normalizeAddress(existing.getAddress()).equals(address))
437	            .toList();
438	        if (housemates.isEmpty()) {
439	            return;
440	        }
441	        if (!Boolean.TRUE.equals(sharesHousehold)) {
442	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
443	        }
444	        String householdId = generateHouseholdId(lastName, address);
445	        owner.setHouseholdId(householdId);
446	        for (Owner housemate : housemates) {
447	            if (!householdId.equals(housemate.getHouseholdId())) {
448	                housemate.setHouseholdId(householdId);
449	                this.clinicService.saveOwner(housemate);
450	            }
451	        }
452	    }
453	
454	    /**
455	     * Builds the stable identifier shared by the members of one household. It is derived purely from
456	     * the normalized last name and address, so every owner of a given household deterministically
457	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
458	     * two normalized fields joined by a single space.
459	     *
460	     * @param normalizedLastName the household's last name, already normalized for comparison
461	     * @param normalizedAddress the household's address, already normalized for comparison
462	     * @return the shared household identifier
463	     */
464	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
465	        String key = normalizedLastName + '�' + normalizedAddress;
466	        try {
467	            byte[] digest = MessageDigest.getInstance("SHA-256")
468	                .digest(key.getBytes(StandardCharsets.UTF_8));
469	            StringBuilder hex = new StringBuilder();
470	            for (byte b : digest) {
471	                hex.append(String.format("%02X", b));
472	                if (hex.length() >= 12) {
473	                    break;
474	                }
475	            }
476	            return hex.substring(0, 12);
477	        } catch (NoSuchAlgorithmException e) {
478	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
479	        }
480	    }
481	
482	    /**
483	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
484	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
485	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
486	     * expands common abbreviations.
487	     *
488	     * @param value the raw last name, or {@code null}
489	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
490	     */
491	    private String normalizeHouseholdField(String value) {
492	        if (value == null) {
493	            return "";
494	        }
495	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
496	    }
497	}
